INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000900020','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000900020","revision":1,"targetId":"80000000-0000-4000-8000-000000009002","prompt":"Die Beschäftigten wollen für bessere Arbeitsbedingungen ___.","instruction":{"en":"Choose the expression or verb form that best completes the German sentence.","de":"Wähle den Ausdruck oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"They plan collective work stoppage as protest.","de":"Sie wollen aus Protest gemeinsam die Arbeit niederlegen."},"slots":[{"id":"expression","label":"Ausdruck oder Verbform","options":[{"id":"0","text":"streiken"},{"id":"1","text":"kündigen"},{"id":"2","text":"bewerben"},{"id":"3","text":"bezahlen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"expression","optionId":"0"}]}],"explanation":{"en":"streiken means stop work in protest. They plan collective work stoppage as protest.","de":"streiken bedeutet aus Protest die Arbeit niederlegen. Sie wollen aus Protest gemeinsam die Arbeit niederlegen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Die Beschäftigten wollen für bessere Arbeitsbedingungen streiken.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L780 (f5461c8f27f031dae72f811b697ec6f2a797e7f860c2ed906b44b1ddb7b16592), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
