INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000900150','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000900150","revision":1,"targetId":"80000000-0000-4000-8000-000000009015","prompt":"Bitte ___ Sie hinter die gelbe Linie zurück.","instruction":{"en":"Choose the expression or verb form that best completes the German sentence.","de":"Wähle den Ausdruck oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"The instruction asks for a step backward.","de":"Die Anweisung verlangt einen Schritt zurück."},"slots":[{"id":"expression","label":"Ausdruck oder Verbform","options":[{"id":"0","text":"springen"},{"id":"1","text":"sitzen"},{"id":"2","text":"treten"},{"id":"3","text":"schlafen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"expression","optionId":"2"}]}],"explanation":{"en":"treten means step or press with a foot. The instruction asks for a step backward.","de":"treten bedeutet einen Schritt machen oder mit dem Fuß drücken. Die Anweisung verlangt einen Schritt zurück."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Bitte treten Sie hinter die gelbe Linie zurück.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L806 (6b30fff8568fe9e7c02ead88267c14ffb10321c2aec14e22966fc70078972f87), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
