INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000900160','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000900160","revision":1,"targetId":"80000000-0000-4000-8000-000000009016","prompt":"Nach dem Waschen müssen die Handtücher erst ___.","instruction":{"en":"Choose the expression or verb form that best completes the German sentence.","de":"Wähle den Ausdruck oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"Wet towels need to lose moisture.","de":"Nasse Handtücher müssen ihre Feuchtigkeit verlieren."},"slots":[{"id":"expression","label":"Ausdruck oder Verbform","options":[{"id":"0","text":"trocknen"},{"id":"1","text":"frieren"},{"id":"2","text":"schmelzen"},{"id":"3","text":"wachsen"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"expression","optionId":"0"}]}],"explanation":{"en":"trocknen means dry or become dry. Wet towels need to lose moisture.","de":"trocknen bedeutet Feuchtigkeit entfernen oder verlieren. Nasse Handtücher müssen ihre Feuchtigkeit verlieren."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach dem Waschen müssen die Handtücher erst trocknen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L808 (0c216ec42ab857ea122c65254a3fccba6dd9a9d5212d7ceb813a1953c7e590aa), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
